const payload = $json;
const intent = payload.llmResult?.intent ?? "unsupported";
const entities = payload.llmResult?.entities ?? {};
const text = String(payload.inboundText ?? "").trim().toLowerCase();
const affirmative = ["si", "sí", "confirmo", "dale", "listo", "acepto"];
const negative = ["no", "cancelar", "detener"];
const isAffirmative = affirmative.some(value => text === value || text.includes(value));
const isNegative = negative.some(value => text === value || text.includes(value));
const mutationIntents = new Set(["create", "update", "cancel", "handoff"]);
const requiresConfirmation = mutationIntents.has(intent);
const idempotencyBase = String(payload.conversation.correlationId);
const confirmation = {
  intent,
  requiresConfirmation,
  confirmed: requiresConfirmation ? isAffirmative : true,
  denied: requiresConfirmation ? isNegative : false,
  prompt: null,
  status: "ready"
};
if (requiresConfirmation && !isAffirmative && !isNegative) {
  confirmation.status = "awaiting-confirmation";
  confirmation.prompt = intent === "create"
    ? "Vas a reservar para " + String(entities.seats ?? "?") + " personas en el restaurante " + String(entities.restaurantId ?? "seleccionado") + " el " + String(entities.date ?? "la fecha indicada") + ". Responde SI para confirmar o NO para cancelar."
    : intent === "update"
      ? "Voy a cambiar tu reserva " + String(entities.reservationId ?? "") + ". Responde SI para confirmar o NO para cancelar."
      : intent === "cancel"
        ? "Voy a cancelar tu reserva " + String(entities.reservationId ?? "") + ". Responde SI para confirmar o NO para cancelar."
        : "Voy a pasarte con una persona del restaurante. Responde SI para continuar o NO para volver al menú.";
}
if (confirmation.denied) {
  confirmation.status = "cancelled-by-user";
}
const operationBodies = {
  availability: { operation: "availability", availability: { restaurantId: entities.restaurantId, date: entities.date, seats: entities.seats } },
  create: { operation: "create", create: { restaurantId: entities.restaurantId, date: entities.date, seats: entities.seats, customerEmail: entities.customerEmail, customerName: entities.customerName, specialRequests: entities.specialRequests ?? null, confirmed: confirmation.confirmed, idempotencyKey: idempotencyBase + ":create", occasionCatalogItemIds: entities.occasionCatalogItemIds ?? [] } },
  list: { operation: "list", list: {} },
  detail: { operation: "detail", detail: { reservationId: entities.reservationId } },
  update: { operation: "update", update: { reservationId: entities.reservationId, date: entities.date, seats: entities.seats, confirmed: confirmation.confirmed, idempotencyKey: idempotencyBase + ":update", expectedConcurrencyToken: entities.expectedConcurrencyToken ?? 0 } },
  cancel: { operation: "cancel", cancel: { reservationId: entities.reservationId, confirmed: confirmation.confirmed, idempotencyKey: idempotencyBase + ":cancel", expectedConcurrencyToken: entities.expectedConcurrencyToken ?? 0, reason: "Solicitud del cliente por WhatsApp" } },
  occasionCatalog: { operation: "occasionCatalog", occasionCatalog: { restaurantId: entities.restaurantId } },
  handoff: { operation: "handoff", handoff: { restaurantId: entities.restaurantId, bookingId: entities.reservationId ?? null, summary: payload.llmResult?.handoffReason ?? payload.inboundText, confirmed: confirmation.confirmed, idempotencyKey: idempotencyBase + ":handoff" } }
};
const templateKey = confirmation.status === "awaiting-confirmation"
  ? "confirmation_prompt"
  : confirmation.status === "cancelled-by-user"
    ? "confirmation_cancelled"
    : intent === "unsupported"
      ? "unsupported"
      : intent + "_result";
return [{ json: { ...payload, confirmation, botRequest: operationBodies[intent] ?? operationBodies.handoff, templateContext: { templateKey, confirmationPrompt: confirmation.prompt } } }];
